    {
      "path": "lib/panel.mjs",
      "content": "// Host half of the floating dev panel (web hosts only; headless profiles\n// never fire the webServer inject, so they stay unchanged).\n//\n// The panel shows the WHOLE plugin, not just hdc: device detail (model,\n// brand, OS, battery), system stats (memory/storage/display), hilog tail,\n// per-device screenshots, and the plugin's own toolchain + knowledge state.\n// Data comes from direct hdc spawns (fixed read-only command set, hard\n// timeouts, watchdog) plus a toolchain bridge from the plugin services.\n// hdc discovery shares one candidate source with the tool layer\n// (lib/hdc-discover.mjs) and adds a PATH fallback so non-default DevEco\n// installs resolve here too (issue #4: tools ok, panel \"hdc not found\").\nimport { execFile } from 'node:child_process'\nimport { readFileSync, accessSync, constants, mkdirSync } from 'node:fs'\nimport { fileURLToPath } from 'node:url'\nimport { tmpdir } from 'node:os'\nimport { join } from 'node:path'\nimport { hdcCandidates, VER_RE, HDC_NOT_FOUND } from './hdc-discover.mjs'\nimport { discoverHdcCandidates } from './studio.mjs'\n\nconst STATE_TTL = 8000\nconst INFO_TTL = 30000\nconst CMD_TIMEOUT = 20000\nconst REFRESH_WATCHDOG = 45000\nconst SHOT_DIR_NAME = 'dsh-hdc-panel'\nconst MAX_DEVICES = 4\nconst NO_DEVICE_HINT = 'No HarmonyOS device/emulator connected. Connect one (hdc_connect 127.0.0.1:5555 for an emulator) or start a DevEco emulator.'\n\n// Direct-spown probe primitives kept behind an injectable seam so tests can\n// simulate machines where only PATH resolves hdc.\nfunction defaultProbe() {\n  return {\n    accessOk(p) { try { accessSync(p, constants.X_OK); return true } catch (e) { return false } },\n    run(file, args, timeoutMs, maxBuffer) {\n      return new Promise((resolve) => {\n        try {\n          execFile(file, args, { timeout: timeoutMs || 12000, maxBuffer: maxBuffer || 65536, windowsHide: true }, (error, stdout, stderr) => {\n            resolve({ ok: !error, stdout: String(stdout || ''), stderr: String(stderr || (error && error.message) || '') })\n          })\n        } catch (e) {\n          // Restricted sandboxes throw EPERM synchronously — degrade like runHdc does.\n          resolve({ ok: false, stdout: '', stderr: String(e && e.message ? e.message : e) })\n        }\n      })\n    },\n  }\n}\n\nexport function parsePanelTargets(text) {\n  const targets = []\n  for (const raw of String(text || '').split(/\\r?\\n/)) {\n    const parts = raw.trim().split(/[\\t ]+/).filter(Boolean)\n    if (parts.length < 2 || parts[0] === '[Empty]') continue\n    const target = { id: parts[0], type: parts[1] || '', state: parts[2] || '', addr: parts[3] || '' }\n    if (/^COM\\d+$/i.test(target.id) || /^COM\\d+$/i.test(target.type) || /^COM\\d+$/i.test(target.addr)) continue\n    if (!/connected/i.test(target.state)) continue\n    targets.push(target)\n  }\n  return targets\n}\n\nexport function panelHdcCandidates() {\n  const list = []\n  const seen = new Set()\n  const add = (value) => {\n    const path = String(value || '')\n    if (!path) return\n    const key = path.toLowerCase()\n    if (seen.has(key)) return\n    seen.add(key)\n    list.push(path)\n  }\n  for (const found of discoverHdcCandidates().candidates) add(found.path)\n  for (const path of hdcCandidates()) add(path)\n  return list\n}\n\nlet hdcPath = ''\nlet hdcError = ''\n// Per-host wiring: the most recent startPanel bridge and its probe seam. The\n// module-level hdc state stays shared across hosts on purpose (one machine,\n// one hdc install).\nlet bridgeRef = null\nlet activeProbe = null\nfunction currentProbe() { return activeProbe || defaultProbe() }\nfunction candidatePaths() {\n  let dyn = []\n  try { dyn = (bridgeRef && typeof bridgeRef.getExtraRoots === 'function' ? bridgeRef.getExtraRoots() : []) || [] } catch (e) { dyn = [] }\n  return hdcCandidates(dyn)\n}\n\nfunction runHdc(args, timeoutMs, maxBuffer) {\n  return new Promise((resolve) => {\n    if (!hdcPath) return resolve({ ok: false, stdout: '', stderr: 'hdc not found' })\n    try {\n      execFile(hdcPath, args, { timeout: timeoutMs || CMD_TIMEOUT, maxBuffer: maxBuffer || 1048576, windowsHide: true }, (error, stdout, stderr) => {\n        if (error) {\n          resolve({ ok: false, timedOut: !!(error && (error.killed === true || error.code === 'ETIMEDOUT')), stdout: String(stdout || ''), stderr: String(stderr || (error && error.message) || '') })\n          return\n        }\n        resolve({ ok: true, stdout: String(stdout || ''), stderr: String(stderr || '') })\n      })\n    } catch (e) {\n      resolve({ ok: false, timedOut: false, stdout: '', stderr: 'hdc spawn unavailable: ' + String(e && e.message ? e.message : e) })\n    }\n  })\n}\n\n// issue #4: discovery now mirrors the tool layer — a path already resolved by\n// the tools wins (they verified it), then the shared candidate list, then PATH.\nasync function discover() {\n  const probe = currentProbe()\n  if (hdcPath) return hdcPath\n  try {\n    const resolved = bridgeRef && bridgeRef.getResolvedHdcPath && bridgeRef.getResolvedHdcPath()\n    if (resolved && typeof resolved === 'string' && probe.accessOk(resolved)) { hdcPath = resolved; hdcError = ''; return hdcPath }\n  } catch (e) { /* fall through to own discovery */ }\n  for (const c of candidatePaths()) {\n    try {\n      if (!probe.accessOk(c)) continue\n      const r = await probe.run(c, ['-v'], 12000, 65536)\n      if (r.ok && VER_RE.test(r.stdout + '\\n' + r.stderr)) { hdcPath = c; hdcError = ''; return hdcPath }\n    } catch (e) { /* try the next candidate */ }\n  }\n  // PATH fallback: same outcome as the tool layer's where.exe/which probes.\n  const which = process.platform === 'win32' ? 'where.exe' : 'which'\n  try {\n    const pr = await probe.run(which, ['hdc'], 12000, 8192)\n    const firstLine = String(pr.stdout || '').split(/\\r?\\n/).map((s) => s.trim()).filter((s) => s && /[\\\\/]/.test(s))[0] || ''\n    if (!pr.ok || !firstLine) throw new Error('no usable PATH hit')\n    const vr = await probe.run(firstLine, ['-v'], 12000, 65536)\n    if (vr.ok && VER_RE.test(vr.stdout + '\\n' + vr.stderr)) { hdcPath = firstLine; hdcError = ''; return hdcPath }\n  } catch (e) { /* restricted sandbox or nothing on PATH — degrade */ }\n  hdcError = HDC_NOT_FOUND\n  return ''\n}\n\nfunction sendJson(res, code, value) {\n  res.writeHead(code, { 'content-type': 'application/json; charset=utf-8', 'cache-control': 'no-store' })\n  res.end(JSON.stringify(value))\n}\nfunction readBody(req) {\n  return new Promise((resolve) => {\n    let data = ''\n    req.on('data', (c) => { data += c })\n    req.on('end', () => { let v = null; try { v = data ? JSON.parse(data) : {} } catch (e) { v = null } resolve(v) })\n    req.on('error', () => resolve(null))\n  })\n}\n\n// ---- device-side parsers (fixed formats, tolerant) ----\nfunction parseBattery(text) {\n  const num = (re) => { const m = re.exec(text); return m ? Number(m[1]) : null }\n  const capacity = num(/capacity:\\s*(\\d+)/)\n  if (capacity === null) return null\n  const temp = num(/temperature:\\s*(\\d+)/)\n  const voltage = num(/voltage:\\s*(\\d+)/)\n  const chargingStatus = num(/chargingStatus:\\s*(\\d+)/)\n  return {\n    capacity,\n    temperature: temp === null ? null : Math.round(temp / 10) / 1,\n    voltage: voltage === null ? null : Math.round(voltage / 10000) / 100,\n    charging: chargingStatus === 1,\n  }\n}\nfunction parseMem(text) {\n  const kb = (re) => { const m = re.exec(text); return m ? Math.round(Number(m[1]) / 1024) : null }\n  return { totalMB: kb(/MemTotal:\\s*(\\d+)/), availMB: kb(/MemAvailable:\\s*(\\d+)/) }\n}\nfunction parseDf(text) {\n  const line = (text || '').split(String.fromCharCode(10)).filter((l) => l.trim())[0] || ''\n  const parts = line.trim().split(/[ ]+/).filter(Boolean)\n  if (parts.length < 5) return null\n  return { size: parts[1], used: parts[2], usePct: parts[4] }\n}\nfunction parseDisplay(text) {\n  const m = /width:\\s*(\\d+),\\s*height:\\s*(\\d+)/i.exec(text)\n  return m ? { w: Number(m[1]), h: Number(m[2]) } : null\n}\n\nlet PLUGIN_VERSION = ''\ntry {\n  PLUGIN_VERSION = JSON.parse(readFileSync(new URL('../package.json', import.meta.url), 'utf8')).version || ''\n} catch (e) { /* 版本读取失败不阻塞 */ }\n\nexport function startPanel(bridge) {\n  const ctx = bridge.ctx\n  bridgeRef = bridge\n  activeProbe = (bridge.probe && typeof bridge.probe.run === 'function') ? bridge.probe : defaultProbe()\n  const shotDir = join(tmpdir(), SHOT_DIR_NAME)\n  try { mkdirSync(shotDir, { recursive: true }) } catch (e) { /* recv 会带出错误 */ }\n  const cache = { state: null, at: 0, info: new Map(), shotBytes: null, shotMeta: { target: '', at: 0 }, display: null, inFlight: null, lastError: '' }\n\n  async function listTargets() {\n    const h = await discover()\n    if (!h) return { ok: false, targets: [], error: hdcError }\n    const r = await runHdc(['list', 'targets', '-v'], 20000)\n    const targets = r.ok ? parsePanelTargets(r.stdout) : []\n    return { ok: r.ok, targets, error: r.ok ? '' : (r.stderr || r.stdout || 'hdc list targets failed') }\n  }\n\n  async function paramGet(target, name) {\n    const r = await runHdc(['-t', target, 'shell', 'param get ' + name], 12000, 4096)\n    return r.ok ? String(r.stdout).trim().replace(/[^A-Za-z0-9 ._-]/g, '').slice(0, 80) : ''\n  }\n\n  async function deviceInfo(target) {\n    const hit = cache.info.get(target)\n    if (hit && Date.now() - hit.at < INFO_TTL) return hit.value\n    const value = { model: '', name: '', brand: '', softwareVersion: '', deviceType: '', apiVersion: '', battery: null }\n    for (const item of [['model', 'const.product.model'], ['name', 'const.product.name'], ['brand', 'const.product.brand'], ['softwareVersion', 'const.product.software.version'], ['deviceType', 'const.product.devicetype'], ['apiVersion', 'const.ohos.apiversion']]) {\n      value[item[0]] = await paramGet(target, item[1])\n    }\n    const batt = await runHdc(['-t', target, 'shell', 'hidumper -s 3302 -a -i'], 15000, 262144)\n    if (batt.ok) value.battery = parseBattery(batt.stdout)\n    cache.info.set(target, { at: Date.now(), value })\n    return value\n  }\n\n  async function systemInfo(target) {\n    const sys = { mem: null, storage: null, display: cache.display }\n    const mem = await runHdc(['-t', target, 'shell', 'cat /proc/meminfo | grep -E \"MemTotal|MemAvailable\"'], 12000, 65536)\n    if (mem.ok) sys.mem = parseMem(mem.stdout)\n    const df = await runHdc(['-t', target, 'shell', 'df -h /data | tail -n 1'], 12000, 65536)\n    if (df.ok) sys.storage = parseDf(df.stdout)\n    return sys\n  }\n\n  async function refresh(shot, shotTarget) {\n    const prior = cache.inFlight\n    if (prior) {\n      if (!shot) return prior\n      try { await prior } catch (e) { /* 前次自处理错误 */ }\n    }\n    cache.inFlight = (async () => {\n      try {\n        const list = await listTargets()\n        const devices = []\n        for (const t of (list.targets || []).slice(0, MAX_DEVICES)) {\n          const info = /connected/i.test(t.state) ? await deviceInfo(t.id) : { model: '', name: '', brand: '', softwareVersion: '', deviceType: '', apiVersion: '', battery: null }\n          devices.push({ id: t.id, type: t.type, state: t.state, ...info })\n        }\n        const primary = (bridge.getPreferred && bridge.getPreferred() && devices.find((d) => d.id === bridge.getPreferred())) || devices[0] || null\n        const system = primary ? await systemInfo(primary.id) : { mem: null, storage: null, display: null }\n        let hilogLines = []\n        let hilogError = ''\n        if (primary) {\n          const lg = await runHdc(['-t', primary.id, 'shell', 'hilog -x | tail -n 60'], 20000, 262144)\n          if (lg.ok) hilogLines = lg.stdout.split(String.fromCharCode(13)).join('').split(String.fromCharCode(10)).filter((l) => l.trim()).slice(-12)\n          else hilogError = (lg.stderr || 'hilog failed').slice(0, 120)\n        }\n        if (shot && primary) {\n          const t = (shotTarget && devices.find((d) => d.id === shotTarget && /connected/i.test(d.state))) ? shotTarget : primary.id\n          const remote = '/data/local/tmp/dsh_panel_shot.jpeg'\n          const cap = await runHdc(['-t', t, 'shell', 'snapshot_display -f ' + remote], 20000, 65536)\n          if (cap.ok) {\n            const disp = parseDisplay(cap.stdout)\n            if (disp) cache.display = disp\n            const local = join(shotDir, 'panel-shot.jpeg')\n            const recv = await runHdc(['-t', t, 'file', 'recv', remote, local], 30000, 1048576)\n            if (recv.ok) {\n              try { cache.shotBytes = readFileSync(local) } catch (e) { cache.shotBytes = null }\n              cache.shotMeta = { target: t, at: Date.now() }\n              cache.lastError = ''\n            } else cache.lastError = (recv.stderr || 'file recv failed').slice(0, 120)\n          } else cache.lastError = (cap.stderr || 'snapshot_display failed').slice(0, 120)\n        }\n        if (cache.display) system.display = cache.display // shot 块可能刚更新了分辨率\n        let toolchain = { studio: '', sdk: 0, devecocli: false, devecocliError: '', knowledge: 0 }\n        if (bridge.toolchain) { try { toolchain = await bridge.toolchain() } catch (e) { /* 保持默认 */ } }\n        cache.state = {\n          ok: list.ok,\n          hdc: hdcPath ? hdcPath.split(String.fromCharCode(92)).join('/').split('/').pop() : '',\n          version: PLUGIN_VERSION,\n          toolchain,\n          devices,\n          system,\n          error: !list.ok ? (list.error || 'hdc list targets failed') : (devices.length === 0 ? NO_DEVICE_HINT : ''),\n          screenshot: cache.shotBytes ? { available: true, target: cache.shotMeta.target, url: '/api2/hdc-bridge/screenshot.jpeg?t=' + cache.shotMeta.at, at: cache.shotMeta.at } : { available: false, target: '', at: 0 },\n          hilog: { available: hilogLines.length > 0, lines: hilogLines, error: hilogError },\n          preferred: bridge.getPreferred ? bridge.getPreferred() : '',\n          lastError: cache.lastError,\n          updatedAt: Date.now(),\n        }\n        cache.at = Date.now()\n      } catch (e) {\n        cache.lastError = String(e && e.message ? e.message : e).slice(0, 200)\n        cache.state = { ok: false, hdc: '', toolchain: { studio: '', sdk: 0, devecocli: false, devecocliError: '', knowledge: 0 }, devices: [], system: { mem: null, storage: null, display: null }, error: hdcError || cache.lastError, screenshot: { available: false, target: '', at: 0 }, hilog: { available: false, lines: [], error: '' }, preferred: '', lastError: cache.lastError, updatedAt: Date.now() }\n        cache.at = Date.now()\n      } finally { cache.inFlight = null }\n    })()\n    return cache.inFlight\n  }\n\n  async function refreshWithWatchdog(shot, shotTarget) {\n    const watchdog = new Promise((resolve) => setTimeout(() => resolve(true), REFRESH_WATCHDOG))\n    await Promise.race([refresh(shot, shotTarget).then(() => false), watchdog])\n    return cache.state\n  }\n\n  if (typeof ctx.inject === 'function') {\n    ctx.inject(['webServer'], (webCtx) => {\n      const ws = webCtx.webServer\n      if (!ws || typeof ws.register !== 'function') return\n      const register = (kind, path, handler) => webCtx.effect(() => ws.register({ kind, path, handler }), 'hdc-bridge panel: ' + path)\n      register('exact', '/api2/hdc-bridge/panel-state', async (req, res) => {\n        if (req.method !== 'GET' && req.method !== 'HEAD') return sendJson(res, 405, { ok: false, error: 'method not allowed' })\n        if (!cache.state || Date.now() - cache.at > STATE_TTL) await refreshWithWatchdog(false, '')\n        sendJson(res, 200, cache.state)\n      })\n      register('exact', '/api2/hdc-bridge/refresh', async (req, res) => {\n        if (req.method !== 'POST') return sendJson(res, 405, { ok: false, error: 'method not allowed' })\n        const body = await readBody(req)\n        await refreshWithWatchdog(!body || body.shot !== false, body && typeof body.target === 'string' ? body.target.trim() : '')\n        sendJson(res, 200, cache.state)\n      })\n      register('exact', '/api2/hdc-bridge/select', async (req, res) => {\n        if (req.method !== 'POST') return sendJson(res, 405, { ok: false, error: 'method not allowed' })\n        const body = await readBody(req)\n        const target = body && typeof body.target === 'string' ? body.target.trim() : ''\n        if (!target) return sendJson(res, 400, { ok: false, error: 'target is required' })\n        const list = await listTargets()\n        const hit = (list.targets || []).find((d) => d.id === target && /connected/i.test(d.state))\n        if (!hit) return sendJson(res, 400, { ok: false, error: 'target is not connected: ' + target })\n        if (bridge.setPreferred) bridge.setPreferred(target)\n        await refreshWithWatchdog(false, '')\n        sendJson(res, 200, cache.state)\n      })\n      register('exact', '/api2/hdc-bridge/screenshot.jpeg', (req, res) => {\n        if (!cache.shotBytes) return sendJson(res, 404, { ok: false, error: 'no screenshot yet; POST /api2/hdc-bridge/refresh with {shot:true} first' })\n        res.writeHead(200, { 'content-type': 'image/jpeg', 'cache-control': 'no-store' })\n        res.end(cache.shotBytes)\n      })\n    })\n  }\n\n  return { refresh, refreshWithWatchdog }\n}\n"
    },
    {
      "path": "lib/skills.mjs",
      "content": "// Runtime skill definitions for dsh-hdc-bridge.\n// The `deveco-cli` skill is an adaptation (translated summary, not a verbatim\n// copy) of the official SKILL.md from gitcode.com/openharmony-sig/deveco-cli,\n// licensed MIT — Copyright (c) 2026 Huawei Device Co., Ltd. The notice line is\n// reproduced inside the skill content and checked by scripts/license-check.mjs.\n//\n// DSH runtime skills must carry BOTH `content` (rendered instructions body)\n// and `source` (the official SkillSource bucket) — the loader rejects one\n// without the other. Runtime-registered skills use the 'runtime' bucket.\nconst skill = (def) => ({ ...def, source: def.source ?? 'runtime' })\n\nexport const SKILLS = [\n  skill({\n    name: 'hdc-bridge',\n    description: 'dsh-hdc-bridge 插件的设备调试闭环用法（观察-定位-操作-验证）。The hdc-bridge device-debug loop usage.',\n    whenToUse: '在已装载 hdc_* 工具的会话里操作 HarmonyOS 真机/模拟器：查看界面、定位控件、点击输入、截图验证、装包与崩溃排查。',\n    content: '# dsh-hdc-bridge 设备调试闭环\\n\\n本技能只讲设备调试工具的用法；ArkTS/API 知识请用 `harmonyos-knowledge` 技能（官方优先、按版本）。\\n\\n## 闭环流程\\n1. hdc_list_targets 确认设备（默认取第一个 Connected 目标，可用 target 覆盖）\\n2. hdc_ui_dump 查看当前界面文本（文本版截图）\\n3. hdc_ui_find 按文本定位控件（返回 bounds 与中心坐标）\\n4. hdc_ui tap / input / swipe / key 操作（每步后用最新 dump 坐标）\\n5. hdc_ui_dump 验证状态变化\\n\\n- 视觉模型：hdc_screenshot → read_image\\n- 排查：hdc_crash（结构化崩溃摘要）/ hdc_hilog（日志）/ hdc_diag（插件状态）\\n- 生命周期：hdc_install（装包）/ hdc_app（query/start/stop/clear-data/uninstall）\\n- 环境体检：hms_setup（hdc/Studio/SDK/devecocli/设备 五项）\\n\\n## 实测经验（本插件团队验证）\\n- 混合字符串输入（数字→字母→数字）：IME 模式切换会稳定吞掉紧跟字母后的字符 → 分段输入 + dump 校验 + 缺失字符补发\\n- 软键盘弹出会改变页面布局：每次点击前使用最新 dump 的坐标；按钮被键盘遮挡时先 hdc_ui key Back 收起键盘\\n- snapshot_display 仅接受 .jpeg（API 10+）\\n- 装包报 9568332 = 签名 profile 未绑定设备 UDID，需在 AGC 添加设备后重新签名\\n- hdc 客户端对远端失败可能仍返回退出码 0：以工具返回的 ok/error 字段为准\\n',\n  }),\n  skill({\n    name: 'deveco-cli',\n    description: '华为官方 DevEco CLI（devecocli）构建/签名/lint/文档通道：hms_build、hms_lint、hms_docs、hms_api_change 的底层命令与约束。',\n    whenToUse: '需要用官方工具链构建/签名/运行鸿蒙应用、跑官方 lint、查官方本地文档、扫描跨版本破坏性 API 变更时；或用户提到 devecocli/DevEco CLI。',\n    content: [\n      '# DevEco CLI（devecocli）技能',\n      '',\n      '> 本技能改写自华为官方仓库 SKILL.md（翻译摘要，非逐字复制）。',\n      '> Copyright (c) 2026 Huawei Device Co., Ltd. — MIT License.',\n      '> 官方原文：https://gitcode.com/openharmony-sig/deveco-cli/blob/develop/SKILL.md',\n      '',\n      '## 入口（本插件工具，优先用它们，参数已校验）',\n      '- hms_build：status / build / run / sign / clean（CLI 缺失时自动回退本机 hvigorw）',\n      '- hms_lint：rules（本机 57+ 官方规则索引）/ read-rule / check（devecocli check lint）',\n      '- hms_docs：search / read / catalog（devecocli docs，官方本地文档库）',\n      '- hms_api_change：versions / diff（devecocli check compat，官方跨版本破坏性变更扫描）',\n      '',\n      '## 安装与工具链形态（二选一）',\n      '- A｜Studio 路线：npm i -g @deveco/deveco-cli（macOS/Windows，Node ≥18），本机装 DevEco Studio ≥6.0。',\n      '- B｜独立 Command Line Tools（CLT）：华为官方 zip 发行版（codelinter/hvigorw/ohpm/emulator/内嵌 SDK），≥26.0.0，**Linux 仅此形态**。解压后把 <clt>/bin 加入 PATH，并设 DEVECO_CLI_CLT_PATH=<解压目录>（deveco-cli 不自动发现 CLT）。下载：developer.huawei.com/consumer/cn/download/command-line-tools-for-hmos。',\n      '- 本插件会自动探测两种形态并把对应根注入环境变量；hms_setup 一眼可查当前 toolchainKind。',\n      '',\n      '## 直接命令速查',\n      '- `build`：编译打包。`--modules <m1> <m2>@<target>` 指定模块；`--product <name>` 打整包；`build clean` 清理。',\n      '- `run`：构建+安装+启动。`--module`、`--device <name|serial>`（多设备必填）、`--uninstall`（先卸载，解决签名 key 变更）、`--skip-build`、`--apply <file>` 增量快速部署（Studio ≥6.1.1）。',\n      '- `check lint [path]`：官方 ArkTS lint。`--fix`、`--format json`（需 Studio ≥6.1.0）、`--limit <n>`。',\n      '- `check compat`：扫描两个 SDK 版本间的破坏性 API 变更。`versions` 列可用版本；`--source-version X --target-version Y --format json --output-path <dir>`；必须 target > source。',\n      '- `signature generate`：自动生成签名材料并写入 build-profile.json5。前置：`auth login` + 项目目录 + 已连接设备。',\n      '- `auth login/status/logout`：华为开发者账号 OAuth（浏览器人工步骤）。',\n      '- `docs search <kw>` / `docs read <id>` / `docs catalog`：官方本地文档检索。',\n      '- `emulator list/start/stop`、`ui layout/screenshot/click/text`、`log --crash --bundle-name X`、`create --app-name X --api-level N`、`skills list/add`。',\n      '',\n      '## 硬性约束',\n      '- Node ≥18；构建/签名/lint 需本机工具链：DevEco Studio ≥6.0（lint 默认，`--format json` 需 ≥6.1.0，`--apply` 需 ≥6.1.1）或独立 Command Line Tools ≥26.0.0（CLT 无内嵌 JDK，CI 场景另配 JAVA_HOME）。',\n      '- 官方标注 [Outside sandbox]：build / run / signature generate / update / check compat —— 在受限沙箱中运行时提示用户放宽策略或人工执行。',\n      '- 签名前置 `auth login` 是浏览器 OAuth，Agent 无法代办；未登录时给用户命令，不重试。',\n      '',\n      '## 错误速查',\n      '- `Not logged in` → devecocli auth login',\n      '- `error:install sign info inconsistent` → devecocli run --uninstall 或 signature generate --force',\n      '- `Provision number exceeds limit` → AGC 控制台删旧测试 profile',\n      '- `Product / Build mode not found` → 检查 build-profile.json5',\n      '- `Multiple entry modules` → build 加 --modules，run 加 --module',\n    ].join('\\n'),\n  }),\n  skill({\n    name: 'harmonyos-knowledge',\n    description: '鸿蒙开发知识层使用纪律：官方优先、按 API 版本分类、许可合规（hms_knowledge / hms_api / hms_docs / hms_api_change / hms_lint）。',\n    whenToUse: '回答任何 ArkTS / ArkUI / API 能力、版本兼容性、废弃 API、lint 规范问题之前；或需要判断某 API 在目标版本是否可用时。',\n    content: [\n      '# 鸿蒙知识层使用纪律（官方优先、版本化、许可合规）',\n      '',\n      '## 数据源层级（严格按序，上层优先）',\n      '**Tier 0 官方一手（本机运行时读取，随用户工具链版本，零再分发）**',\n      '- hms_api：本机 SDK .d.ts，每条 API 带 @since/@deprecated/@syscap，精确到 API 版本 —— 回答\"某 API 何时有/何时废弃\"的首选',\n      '- hms_docs：devecocli 官方本地文档库（开发指南/API 参考）',\n      '- hms_api_change：官方跨版本破坏性变更扫描（check compat）',\n      '- hms_lint rules：本机 DevEco 内置官方 lint 规则（Apache-2.0，本地读取）',\n      '**Tier 1 随包内置（离线可用，无需 Studio/SDK/网络）**',\n      '- hms_knowledge：OpenHarmony 官方文档逐字节选（CC-BY-4.0 已署名）—— 28 篇高频官方文档：API 模块（promptAction/router/notification/vibrator/http/ws/preferences/util/uiAbility/权限/context/hilog/abilityManager…）、窗口 window/Window 类、导航组件 Navigation、应用模型与 ArkTS 状态管理指南。catalog 列题 → read 先看目录再按小节读 → search 按关键词找题/小节',\n      '- deveco-cli 技能（官方 SKILL.md 改写，MIT 已声明）',\n      '**Tier 2 用户自装（仅指路，绝不随包）**：harmony-next.skills 等社区包（无 LICENSE，不可再分发）；官方 web 文档 developer.huawei.com（在线检索时优先官方站）',\n      '',\n      '## 查询速查',\n      '- 概念/用法/示例（人读文档）：先 hms_knowledge（离线随包，秒回）；全量官方库走 hms_docs（需 devecocli）',\n      '- 签名/版本/废弃判定（机读精确）：hms_api 的 @since/@deprecated/@syscap',\n      '- 文档正文里的\"起始版本/API version\"标注同样可信，回答时同步标注',\n      '',\n      '## 官方测试框架指路（canonical 在 ohpm/Gitee，不在 GitHub）',\n      '- hypium（@ohos/hypium，Apache-2.0）：官方单元测试框架，describe/it/expect 风格，支持 HAP/HAR 测试；仓库 gitee.com/openharmony/testfwk_arkxtest，ohpm 安装',\n      '- hamock（@ohos/hamock，Apache-2.0）：官方 mock 框架，与 hypium 配对做依赖替换；同一仓库的 hamock/ 子目录',\n      '- 这两个项目没有 GitHub canonical——找源码与示例以 Gitee/ohpm 为准；仅指路，不复制内容',\n      '',\n      '## 版本纪律（鸿蒙知识随版本变化，不止新增）',\n      '1. 回答问题前先确定目标 API 版本：hms_setup 一次取齐三处来源 —— 项目 build-profile.json5 compatibleSdkVersion → 设备 `param get const.ohos.apiversion` → 本机 SDK apiVersion',\n      '2. 三处不一致时显式提示用户（例如 SDK=23 而真机=24），并建议用 hms_api_change diff 查差异',\n      '3. API 标注 @since N 表示 N 起才存在；@deprecated since M 表示 M 起不推荐，找替代 API',\n      '4. 旧版知识回答新版问题 = 高危错误：宁可先 hms_api 查询再回答',\n      '5. 引用知识时标注来源层级与版本（如 \"hms_api@SDK23：since 15，目标 23 可用\"）',\n      '',\n      '## 许可纪律',\n      '- 本机读取（SDK .d.ts / codelinter 规则）= 合法，但不得把这些内容复制进生成物再分发',\n      '- 无 LICENSE 资源只可引用链接，不可复制内容',\n      '- 引用官方内容时保留版权与来源',\n    ].join('\\n'),\n  }),\n  skill({\n    name: 'deveco-compile',\n    description: 'HarmonyOS compile loop: switch_cwd, arkts_check, build_project, start_app, and hdc_log.',\n    whenToUse: 'Use when building, checking, deploying, or collecting logs for a HarmonyOS project, or when the user names any of the compile-assistance tools.',\n    content: [\n      '# HarmonyOS Compile Loop',\n      '',\n      '1. `switch_cwd`: point this conversation at the application root.',\n      '2. `arkts_check`: run the fast SDK ets-loader check after editing `.ets` files.',\n      '3. `build_project`: package the application. It verifies that a fresh `.hap` was produced and uses direct `hvigorw` when the devecocli channel does not complete.',\n      '4. `start_app`: deploy the latest package and start its entry ability. It first uses devecocli, then falls back to `hdc` installation and launch.',\n      '5. `hdc_log`: collect, clear, or list device logs. Use bundle or PID filters for runtime diagnosis.',\n      '',\n      '## Boundaries',\n      '- Do not construct ad-hoc `hvigorw` commands. The registered tools preserve the project cwd, quote arguments, and verify artifacts.',\n      '- `start_app` does not build. Run `build_project` first. For signing and account login use `hms_build` and the `deveco-cli` skill.',\n      '- `arkts_check` requires the DevEco Studio SDK ets-loader. A full `build_project` remains the fallback when it is unavailable.',\n      '- For device UI inspection, screenshots, installation lifecycle, and crash files use the `hdc-bridge` skill.',\n      '',\n      '## Common Results',\n      '- `HarmonyOS project not found`: run `switch_cwd` with the directory containing `build-profile.json5`.',\n      '- No updated `.hap`: inspect the build output; a reported success without an artifact is treated as a failure.',\n      '- No device: call `hdc_log` with `action=list_devices` or `hdc_list_targets`, then start or connect the intended target.',\n    ].join('\\n'),\n  }),\n  skill({\n    name: 'harmony-next',\n    description: 'Guidance for optional Harmony Next community skills installed by the user.',\n    whenToUse: 'Use when the user asks about an already installed harmony-next community skill or its local tooling.',\n    content: [\n      '# Harmony Next Guidance',\n      '',\n      'The Harmony Next community skill is optional and is not bundled by this plugin.',\n      'Use the locally installed skill documentation as the source of truth for its commands and workflow.',\n      'For the plugin-provided path, use `deveco-compile` for build and deployment, `hdc-bridge` for device actions, and `harmonyos-knowledge` for versioned API references.',\n    ].join('\\n'),\n  }),\n]\n"
    },
    {
      "path": "lib/compile-output.mjs",
      "content": "// Build-log formatting for build_project: ANSI stripping, per-stream\n// truncation to the last N lines, and an exitCode-derived status line that is\n// always appended after truncation so evaluators scanning the tail are not\n// fooled by stderr warning floods.\n// Plain-JS port of the DevEco Code tool helper:\n//   gitcode.com/openharmony-sig/deveco-code\n//   packages/opencode/src/tool/lib/build-project-output.ts\n// Copyright (c) 2026 Huawei Device Co., Ltd. — Apache-2.0 (see notices.json).\n\nexport const MAX_OUTPUT_LINES = 50\nexport const TRUNCATE_NOTICE = '--- The log is too long, only the last 50 lines are kept ---'\n\n// Zero-dependency ANSI escape stripper (covers CSI/OSC sequences).\nconst ANSI_RE = /[\\u001B\\u009B][[\\]()#;?]*(?:(?:(?:[a-zA-Z\\d]*(?:;[-a-zA-Z\\d/#&.:=?%@~_]+)*)?\\u0007)|(?:(?:\\d{1,4}(?:;\\d{0,4})*)?[\\dA-PR-TZcf-nq-uy=><~]))/g\n\nexport function stripAnsi(text) {\n  return String(text ?? '').replace(ANSI_RE, '')\n}\n\nfunction splitLines(text) {\n  if (!text) return []\n  return String(text).split(/\\r?\\n/)\n}\n\nfunction takeLastLines(lines, max) {\n  if (max <= 0 || lines.length === 0) return { lines: [], truncated: false }\n  if (lines.length <= max) return { lines, truncated: false }\n  return { lines: lines.slice(-max), truncated: true }\n}\n\nexport function truncateOutput(text) {\n  const lines = splitLines(text)\n  if (lines.length <= MAX_OUTPUT_LINES) return { text, truncated: false, preview: text }\n  const preview = lines.slice(-MAX_OUTPUT_LINES).join('\\n')\n  return { text: `${TRUNCATE_NOTICE}\\n${preview}`, truncated: true, preview }\n}\n\n/** Concatenate streams as stdout then stderr (no section labels). */\nexport function formatStdoutStderr(stdout, stderr) {\n  const out = stripAnsi(stdout)\n  const err = stripAnsi(stderr)\n  if (out && err) return `${out}${err}`\n  return out || err\n}\n\n/**\n * Status line derived from exitCode. Always appended after truncation so\n * evaluators that scan the last N lines for \"Build completed successfully\"\n * are not fooled by stderr warning floods.\n */\nexport function formatBuildStatusLine(exitCode) {\n  return exitCode === 0\n    ? `Build completed successfully (exitCode=${exitCode})`\n    : `BUILD FAILED (exitCode=${exitCode})`\n}\n\n/**\n * Format build logs for the model. Truncates stdout and stderr separately so a\n * long stderr warning tail cannot push \"Build completed successfully\" out of\n * the last-N-lines window, then always appends an exitCode-based status line.\n */\nexport function formatBuildProjectOutput(opts) {\n  const maxLines = opts.maxLines ?? MAX_OUTPUT_LINES\n  const out = stripAnsi(opts.stdout)\n  const err = stripAnsi(opts.stderr)\n  const fullBody = formatStdoutStderr(opts.stdout, opts.stderr)\n  const status = formatBuildStatusLine(opts.exitCode)\n  const full = fullBody ? `${fullBody}\\n${status}` : status\n\n  const outLines = splitLines(out)\n  const errLines = splitLines(err)\n  const total = outLines.length + errLines.length\n\n  let outBudget\n  let errBudget\n  if (outLines.length === 0) {\n    outBudget = 0\n    errBudget = maxLines\n  } else if (errLines.length === 0) {\n    outBudget = maxLines\n    errBudget = 0\n  } else if (total <= maxLines) {\n    outBudget = outLines.length\n    errBudget = errLines.length\n  } else {\n    outBudget = Math.ceil(maxLines / 2)\n    errBudget = Math.floor(maxLines / 2)\n    if (outLines.length < outBudget) {\n      errBudget = maxLines - outLines.length\n      outBudget = outLines.length\n    } else if (errLines.length < errBudget) {\n      outBudget = maxLines - errLines.length\n      errBudget = errLines.length\n    }\n  }\n\n  const outCut = takeLastLines(outLines, outBudget)\n  const errCut = takeLastLines(errLines, errBudget)\n  const truncated = total > maxLines || outCut.truncated || errCut.truncated\n\n  const previewBody = `${outCut.lines.join('\\n')}${errCut.lines.join('\\n')}`\n  const preview = previewBody ? `${previewBody}\\n${status}` : status\n  const text = truncated ? `${TRUNCATE_NOTICE}\\n${preview}` : preview\n\n  return { text, truncated, preview, full }\n}\n"
    },
    {
      "path": "lib/compile-session-cwd.mjs",
      "content": "// Session-scoped HarmonyOS project root for the compile-assistance tools\n// (switch_cwd stores it; build_project / start_app / arkts_check / hdc_log\n// resolve it). In-process Map keyed by session id, mirroring the DevEco Code\n// session-cwd helper:\n//   gitcode.com/openharmony-sig/deveco-code\n//   packages/opencode/src/tool/lib/session-cwd.ts\n//   packages/opencode/src/tool/switch-cwd.ts\n// Copyright (c) 2026 Huawei Device Co., Ltd. — Apache-2.0 (see notices.json).\n\nimport { statSync } from 'node:fs'\nimport { join } from 'node:path'\n\nconst sessionCwd = new Map()\n\nexport function setSessionCwd(sessionID, cwd) {\n  const id = String(sessionID || '').trim()\n  const dir = String(cwd || '').trim()\n  if (!id || !dir) return\n  sessionCwd.set(id, dir)\n}\n\nexport function getSessionCwd(sessionID) {\n  if (!sessionID) return undefined\n  return sessionCwd.get(sessionID)\n}\n\nexport function clearSessionCwd(sessionID) {\n  if (!sessionID) {\n    sessionCwd.clear()\n    return\n  }\n  sessionCwd.delete(sessionID)\n}\n\n/**\n * Stage app root, or project root with hvigor OHPM metadata (not a submodule\n * folder).\n */\nexport function isHarmonyApplicationRoot(dir) {\n  const isFile = (file) => {\n    try {\n      return statSync(file).isFile()\n    } catch {\n      return false\n    }\n  }\n  if (isFile(join(dir, 'AppScope', 'app.json5'))) return true\n  if (!isFile(join(dir, 'build-profile.json5'))) return false\n  return isFile(join(dir, 'oh-package.json5')) || isFile(join(dir, 'oh-package.json'))\n}\n"
    },
    {
      "path": "scripts/smoke.mjs",
      "content": "// dsh-hdc-bridge regression suite (no real hdc required — fake shell drives\n// everything except panel.mjs, whose direct hdc spawn is exercised only for\n// its graceful-degradation paths). Run: node scripts/smoke.mjs\nconst MOD_URL = new URL('../lib/host.js', import.meta.url).href\nimport { readFile, readdir } from 'node:fs/promises'\nimport { existsSync, mkdtempSync, writeFileSync, mkdirSync, rmSync } from 'node:fs'\nimport { tmpdir } from 'node:os'\nimport { join as joinPath } from 'node:path'\nimport { isDevEcoProductInfo, discoverHdcCandidates, parseRegistryPathEntries, parseRegistryPaths, splitPathEntries } from '../lib/studio.mjs'\nimport { snippetFor } from '../lib/sdk-dts.mjs'\nimport * as compileOut from '../lib/compile-output.mjs'\nimport { formatCommandResult, formatDeviceSelectionPrompt } from '../lib/compile-cli.mjs'\nimport { panelHdcCandidates, parsePanelTargets } from '../lib/panel.mjs'\nlet failures = 0\nfunction check(name, cond, extra) {\n  console.log((cond ? 'PASS' : 'FAIL') + ' [' + name + ']' + (cond || extra === undefined ? '' : ' ' + extra))\n  if (!cond) failures += 1\n}\n// ---------- fake harness ----------\nconst registered = []\nconst skills = []\nconst routes = []\nconst seen = []\nlet connected = ['DEV_A', 'DEV_B']\nfunction deviceRows(list) { return list.map((id) => id + '\\t\\ttcp\\tConnected\\tlocalhost\\thdc').join('\\n') }\n// First matching rule answers the command; default stays empty-success so\n// unmatched probes degrade exactly like a silent failure would.\nconst DEFAULT_RULES = [\n  [(c) => c.includes('list targets'), () => deviceRows(connected)],\n  [(c) => c.includes('hilog'), () => 'I 00000/HiLog: smoke line'],\n  [(c) => c.includes('PSVersionTable'), () => '7'],\n  [(c) => c.includes('hdc') && c.includes('-v'), () => 'Ver: 3.2.0c'],\n]\nfunction outcomeFor(rules, spec, sink) {\n  const cmd = spec.command || ''\n  if (sink) sink.push(cmd)\n  for (const [pred, reply] of rules) {\n    if (pred(cmd)) { const text = typeof reply === 'function' ? reply(cmd) : reply; return { stdout: { text }, stderr: { text: '' }, exitCode: 0, timedOut: false } }\n  }\n  return { stdout: { text: '' }, stderr: { text: '' }, exitCode: 0, timedOut: false }\n}\nfunction makeFakeShell(rules, sink) {\n  return {\n    resolve: (q) => q,\n    // DSH 0.2.0-rc.2: execute(spec) returns a process handle whose result()\n    // (a method) resolves to the outcome the old run() returned directly.\n    execute: async (spec) => ({ result: () => outcomeFor(rules, spec, sink) }),\n  }\n}\n// The pre-0.2.0 seam: ShellExecutor.run(spec) resolves with the outcome itself.\nfunction makeLegacyShell(rules, sink) {\n  return { resolve: (q) => q, run: async (spec) => outcomeFor(rules, spec, sink) }\n}\n// Minimal fake Command Line Tools tree for the discovery and gate regressions.\nfunction makeCltFixture(prefix) {\n  const fx = mkdtempSync(joinPath(tmpdir(), prefix))\n  const w = (rel, content) => {\n    const p = joinPath(fx, rel)\n    mkdirSync(joinPath(p, '..'), { recursive: true })\n    writeFileSync(p, content)\n  }\n  return { fx, w }\n}\nconst fakeShell = () => makeFakeShell(DEFAULT_RULES, null)\nfunction makeCtx() {\n  return {\n    get(n) { if (n === 'skills') return { register: (s) => { skills.push(s); return () => {} } }; return undefined },\n    inject(names, cb) { if (names.includes('webServer')) cb({ webServer: { register: (r) => routes.push(r) }, effect: (fn) => fn() }) },\n    shell: makeFakeShell(DEFAULT_RULES, seen),\n    tools: { register: (d) => registered.push(d) },\n    effect: (fn) => fn(),\n  }\n}\nconst mod = await import(MOD_URL + '?t=' + Date.now())\nmod.apply(makeCtx())\nconst exec = { agent: { session: undefined } }\nconst lastTarget = () => { const m = [...seen].reverse().find((c) => c.includes('-t')); return m ? (m.match(/-t '([^']+)'/) || [])[1] : '' }\n\n// ---------- 1. registration ----------\ncheck('tools=25', registered.length === 25, 'got ' + registered.length)\ncheck('skills=5', skills.length === 5, 'got ' + skills.length)\ncheck('skills-source-runtime', skills.every((s) => s.source === 'runtime'), JSON.stringify(skills.map((s) => s.name + ':' + s.source)))\ncheck('compile-tools-registered', ['switch_cwd', 'build_project', 'arkts_check', 'start_app', 'hdc_log'].every((name) => registered.some((tool) => tool.name === name)))\ncheck('routes=4', routes.length === 4, routes.map((r) => r.path).join(','))\nconst registryFixture = 'HKEY_LOCAL_MACHINE\\\\SOFTWARE\\\\WOW6432Node\\\\Huawei\\\\DevEco Studio\\\\243\\r\\n    (Default)    REG_SZ    C:\\\\Users\\\\tester\\\\DevEco Studio\\r\\n    Build    REG_SZ    243.1\\r\\n'\ncheck('studio-registry-path-parser', parseRegistryPaths(registryFixture)[0] === 'C:\\\\Users\\\\tester\\\\DevEco Studio')\ncheck('studio-path-entry-parser', JSON.stringify(splitPathEntries('C:\\\\DevEco Studio\\\\bin;D:\\\\tools', ';')) === JSON.stringify(['C:\\\\DevEco Studio\\\\bin', 'D:\\\\tools']))\nconst pathRegistryFixture = 'Path    REG_EXPAND_SZ    C:\\\\DevEco Studio\\\\sdk\\\\default\\\\openharmony\\\\toolchains;D:\\\\tools\\\\bin\\r\\n'\ncheck('studio-registry-path-entry-parser', JSON.stringify(parseRegistryPathEntries(pathRegistryFixture)) === JSON.stringify(['C:\\\\DevEco Studio\\\\sdk\\\\default\\\\openharmony\\\\toolchains', 'D:\\\\tools\\\\bin']))\ncheck('studio-product-identity', isDevEcoProductInfo({ name: 'DevEco Studio', productVendor: 'Huawei' }) && !isDevEcoProductInfo({ name: 'PyCharm', productVendor: 'JetBrains' }))\nconst discoveredHdc = discoverHdcCandidates().candidates[0]\nif (discoveredHdc) {\n  check('panel-uses-discovered-hdc', panelHdcCandidates().includes(discoveredHdc.path), JSON.stringify({ discoveredHdc, panelCandidates: panelHdcCandidates().slice(0, 4) }))\n} else {\n  console.log('SKIP [panel-uses-discovered-hdc] no discoverable hdc candidates on this host')\n}\nconst targetFixture = 'HUAWEI_MATEPAD\\ttcp\\tConnected\\t192.168.1.11:12345\\nCOM3\\tCOM3\\nCOM4\\tCOM4\\tDisconnected\\n'\ncheck('panel-filters-serial-targets', JSON.stringify(parsePanelTargets(targetFixture).map((target) => target.id)) === JSON.stringify(['HUAWEI_MATEPAD']))\nconst snippetFixture = 'export function update(asset: Asset, query: Query): void\\nexport function query(asset: Asset): Result\\nexport function remove(asset: Asset): void'\nconst queryWindows = snippetFor(snippetFixture, 'query', 40)\ncheck('sdk-snippet-exact-name', queryWindows.length === 1 && queryWindows[0].text.includes('function query'))\ncheck('build-output-failure-status', compileOut.formatBuildProjectOutput({ stdout: 'Build completed successfully (exitCode=0)', stderr: 'hvigor ERROR: ENOENT', exitCode: 1 }).text.includes('BUILD FAILED (exitCode=1)'))\ncheck('build-output-truncate-export', compileOut.truncateOutput(Array.from({ length: 55 }, (_, i) => 'line-' + i).join('\\n')).truncated === true)\ncheck('compile-cli-source-formatting', formatDeviceSelectionPrompt('\\u001b[32mName  Kind\\nPhone  device\\u001b[0m', '').includes('请指定要使用的设备。') && !/\\u001b\\[/.test(formatCommandResult('devecocli device list', { stdout: '\\u001b[32mout\\u001b[0m', stderr: '' })))\n\n// ---------- 2. device memory ----------\nconst hilog = registered.find((t) => t.name === 'hdc_hilog')\nconst listTool = registered.find((t) => t.name === 'hdc_list_targets')\nseen.length = 0; await hilog.execute({ lines: 10 }, exec); const t1 = lastTarget()\nseen.length = 0; await hilog.execute({ lines: 10, target: 'DEV_B' }, exec); const t2 = lastTarget()\nseen.length = 0; await hilog.execute({ lines: 10 }, exec); const t3 = lastTarget()\nconnected = ['DEV_A']; seen.length = 0; await hilog.execute({ lines: 10 }, exec); const t4 = lastTarget()\ncheck('memory-flow', t1 === 'DEV_A' && t2 === 'DEV_B' && t3 === 'DEV_B' && t4 === 'DEV_A', JSON.stringify([t1, t2, t3, t4]))\nconnected = ['DEV_A', 'DEV_B']\nconst lr = await listTool.execute({}, exec)\ncheck('list-preferred', lr.preferred === 'DEV_A' && lr.preferredActive === true, JSON.stringify({ preferred: lr.preferred, active: lr.preferredActive }))\nconst startTool = registered.find((tool) => tool.name === 'start_app')\nconst noDeviceStart = await startTool.execute({}, exec)\ncheck('start-app-no-hvd-does-not-auto-deploy', noDeviceStart.ok === false && !noDeviceStart.hdcFallback && noDeviceStart.availableDevices.some((target) => target.id === 'DEV_A') && /请指定要使用的设备/.test(noDeviceStart.text || '') && !/devecocli background|未检测到可用设备/.test(noDeviceStart.text || ''), JSON.stringify(noDeviceStart))\n\n// Upstream regression cases: an already connected tconn is success, and\n// Windows absolute paths are normalized even when the mounted host shell is\n// not PowerShell (for example Git Bash).\nconst connectTool = registered.find((tool) => tool.name === 'hdc_connect')\nDEFAULT_RULES.unshift([(c) => c.includes('tconn'), () => 'Target is connected, repeat operation'])\nconst repeatConnect = await connectTool.execute({ address: '192.168.1.11:34569' }, exec)\ncheck('connect-repeat-idempotent', repeatConnect.ok === true, JSON.stringify(repeatConnect))\nDEFAULT_RULES.shift()\nconst installTool = registered.find((tool) => tool.name === 'hdc_install')\nseen.length = 0\nawait installTool.execute({ hapPath: 'E:/ScribePad/entry/build/default/outputs/default/app.hap' }, exec)\nconst installLine = [...seen].reverse().find((line) => line.includes('install')) || ''\ncheck('install-absolute-path-normalized', process.platform === 'win32' ? (!installLine.includes('E:/') && installLine.includes('E:\\\\ScribePad\\\\entry\\\\build')) : installLine.includes('E:/ScribePad'), installLine)\n\n// A fresh host instance must initialize hdc itself before the first\n// list_devices call; this guards the regression where the result depended on\n// an earlier hdc_* tool having already discovered the executable.\nconst freshRegistered = []\nmod.apply({\n  get() { return undefined },\n  inject() {},\n  shell: fakeShell(),\n  tools: { register: (d) => freshRegistered.push(d) },\n  effect: (fn) => fn(),\n})\nconst freshList = freshRegistered.find((tool) => tool.name === 'hdc_log')\nconst firstList = await freshList.execute({ action: 'list_devices' }, exec)\ncheck('list-devices-first-call', firstList.ok === true && firstList.deviceCount === 2 && firstList.preferred === 'DEV_A' && firstList.preferredActive === true && Array.isArray(firstList.targets), JSON.stringify(firstList))\nlet renderedList = ''\ntry { renderedList = freshList.output.render({}, firstList)[0].text } catch (error) { renderedList = String(error && error.message ? error.message : error) }\nlet renderedJson = null\ntry { renderedJson = JSON.parse(renderedList) } catch { /* assertion below reports the raw text */ }\ncheck('list-devices-render-json', !!renderedJson && Array.isArray(renderedJson.devices) && Array.isArray(renderedJson.targets) && 'preferredActive' in renderedJson, renderedList)\n\nconst hostSrc = await readFile(new URL('../lib/host.js', import.meta.url), 'utf8')\n// Regression for issue #7: local staging paths must go through joinPath —\n// hardcoded backslash separators break every POSIX host (macOS/Linux).\ncheck('no-hardcoded-backslash-dsh-paths', !/\\\\\\\\\\.dsh-hdc|'\\\\\\\\dsh-shot-/.test(hostSrc) && hostSrc.includes(\"joinPath(root, '.dsh-hdc', 'screenshots')\") && hostSrc.includes(\"joinPath(stageDir, 'layout-'\"), 'hardcoded backslash staging paths found in host.js')\ncheck('hvigor-build-log-isolation', /HVIGOR_USER_HOME/.test(hostSrc) && /build-logs/.test(hostSrc) && /dsh-hvigor-tmp/.test(hostSrc) && /retriedIsolatedHome/.test(hostSrc) && hostSrc.includes(\"joinPath(base, '.dsh-hvigor-tmp')\") && /--stop-daemon/.test(hostSrc) && /--no-daemon/.test(hostSrc) && /JAVA_HOME/.test(hostSrc))\ncheck('hvigor-jbr-daemon-reset', /daemonStopped: true/.test(hostSrc) && /HVIGOR_USER_HOME/.test(hostSrc) && /app_packing_tool\\.jar/.test(hostSrc) && /onDeviceTest/.test(hostSrc))\ncheck('hms-build-no-empty-success', hostSrc.includes('function buildResultOk') && hostSrc.includes('buildResultOk(r) && !deMojo') && hostSrc.includes('buildResultOk(r) && !mojo') && hostSrc.includes('artifactVerified'))\ncheck('hms-build-run-ensures-hdc', hostSrc.includes('await ensureHdc(policy)') && hostSrc.includes('install({ hapPath: hap, target: q(args.device) || undefined }, policy)'))\ncheck('hms-build-run-verifies-mission', hostSrc.includes('missionVerified: Boolean(mission.ok)') && hostSrc.includes(\"appAction({ action: 'start', bundleName, target: q(args.device) || undefined }, policy)\"))\ncheck('build-project-clean-rebuilds', hostSrc.includes(\"const cleanArgv = ['build', 'clean']\") && hostSrc.includes(\"compileCli.commandText(cleanArgv) + ' && ' + compileCli.commandText(argv)\") && hostSrc.includes(\"task: 'assembleHap'\"))\ncheck('hms-build-output-strips-ansi', hostSrc.includes('output: compileOut.stripAnsi(fb.output)') && hostSrc.includes('output: compileOut.stripAnsi(deOutput)'))\ncheck('hms-emulator-list-text-fallback', hostSrc.includes(\"['emulator', 'list', '--format', 'json']\") && hostSrc.includes(\"['emulator', 'list']\") && hostSrc.includes('No emulator instances found.'))\ncheck('hms-api-change-text-fallback', hostSrc.includes(\"['check', 'compat', 'versions', '--format', 'json']\") && hostSrc.includes(\"['check', 'compat', 'versions']\") && hostSrc.includes('compat versions returned no output.'))\ncheck('hms-api-change-diff-json-output', hostSrc.includes('changes: json != null ? json : null') && hostSrc.includes('JSON.stringify(json, null, 2)'))\ncheck('hvigor-build-cache-dir-env', /BUILD_CACHE_DIR/.test(hostSrc) && /cache-env/.test(hostSrc) && /hvigorUserHome/.test(hostSrc) && /buildCacheDir/.test(hostSrc))\ncheck('hvigor-pnpm-prewarm', /preWarmPnpm/.test(hostSrc) && /wrapper.*tools/.test(hostSrc) && /pnpm\\.cmd/.test(hostSrc))\ncheck('hms-api-change-stderr-merge', /mergeStderr/.test(hostSrc) && /2>&1/.test(hostSrc))\ncheck('hms-emulator-hdc-backfill', /hdcBackfilled/.test(hostSrc) && /isEmulatorTarget/.test(hostSrc))\ncheck('hms-emulator-start-poll', /pollEmulatorRunning/.test(hostSrc) && /verifiedBy/.test(hostSrc))\ncheck('hms-emulator-hdc-ensure', hostSrc.includes('await ensureHdc(policy)') && /hdcBackfilled/.test(hostSrc) && /pollEmulatorRunning/.test(hostSrc))\ncheck('hms-emulator-start-ok-fix', hostSrc.includes('ok: res.ok && poll.running'))\ncheck('hms-emulator-start-idempotent', hostSrc.includes('start is idempotent') && hostSrc.includes('i.status || i.state'))\ncheck('hms-api-change-local-version-guard', hostSrc.includes(\"const COMPAT_MIN = '26.0.0.810'\") && /localVersionGuard/.test(hostSrc) && /compatErrorText/.test(hostSrc))\ncheck('hms-build-hvigor-diagnostics', /hvigorDiag\\(/.test(hostSrc) && /daemonStopped:/.test(hostSrc) && /hvigorUserHome:/.test(hostSrc) && /buildCacheDir:/.test(hostSrc))\n\n// ---------- 3. panel routes (env-agnostic paths) ----------\nconst mkRes = () => ({ statusCode: 0, headers: {}, body: '', writeHead(c, h) { this.statusCode = c; this.headers = h }, end(b) { this.body = b } })\nconst mkReq = (body) => { const q = { method: 'POST' }; q.on = (ev, cb) => { if (ev === 'data') cb(JSON.stringify(body)); else if (ev === 'end') cb() }; return q }\nconst ps = routes.find((r) => r.path === '/api2/hdc-bridge/panel-state')\nconst sel = routes.find((r) => r.path === '/api2/hdc-bridge/select')\nconst shot = routes.find((r) => r.path === '/api2/hdc-bridge/screenshot.jpeg')\nconst r1 = mkRes(); await ps.handler({ method: 'GET', on() {} }, r1)\nlet s1 = null; try { s1 = JSON.parse(r1.body) } catch (e) {}\ncheck('panel-state-json', r1.statusCode === 200 && s1 && typeof s1 === 'object' && 'devices' in s1 && 'preferred' in s1 && 'toolchain' in s1, JSON.stringify(Object.keys(s1 || {})))\nconst r2 = mkRes(); await sel.handler(mkReq({ target: 'NOT_A_DEVICE' }), r2)\ncheck('select-rejects-unknown', r2.statusCode === 400, 'got ' + r2.statusCode)\nconst r3 = mkRes(); await shot.handler({ method: 'GET', on() {} }, r3)\ncheck('shot-404-empty', r3.statusCode === 404, 'got ' + r3.statusCode)\n\n// ---------- 4. knowledge layer ----------\nconst kn = registered.find((t) => t.name === 'hms_knowledge')\nconst cat = await kn.execute({ action: 'catalog' }, exec)\ncheck('catalog>=28', cat.total >= 28, 'got ' + cat.total)\nconst rd = await kn.execute({ action: 'read', id: 'sensor', section: 'getSingleSensor' }, exec)\ncheck('sensor-section', rd.ok === true && typeof rd.content === 'string' && rd.content.length > 0)\nconst sf = await kn.execute({ action: 'search', keywords: '文件' }, exec)\ncheck('search-fileFs', sf.results[0] && sf.results[0].id === 'fileFs', JSON.stringify(sf.results[0] && sf.results[0].id))\nconst wh = await kn.execute({ action: 'read', id: 'hilog', section: 'info' }, exec)\ncheck('read-hilog', wh.ok === true && /hilog/i.test(wh.content || ''))\nconst wn = await kn.execute({ action: 'read', id: 'window-Window', section: 'setUIContent' }, exec)\ncheck('read-window-setUIContent', wn.ok === true && /setUIContent/.test(wn.content || ''))\nconst nv = await kn.execute({ action: 'read', id: 'Navigation', section: '接口' }, exec)\ncheck('read-navigation-api', nv.ok === true && /Navigation/.test(nv.content || ''))\nconst sw = await kn.execute({ action: 'search', keywords: '日志' }, exec)\ncheck('search-hilog', sw.results.some((x) => x.id === 'hilog'), JSON.stringify(sw.results.slice(0, 3).map((x) => x.id)))\n\n// ---------- 4b. client bundle guards (official client-plugin contract) ----------\n// The browser half uses the input-row capsule as its only entry and anchors the\n// panel above it. The replay below checks the real loader wiring and confirms\n// that no portal or persisted floating-window machinery regresses back in.\nconst clientSrc = await readFile(new URL('../lib/client.js', import.meta.url), 'utf8')\ncheck('client-loader-factory', /window\\.__ModuleLoader__\\.load\\(/.test(clientSrc) && /exports\\.apply/.test(clientSrc))\ncheck('client-react-module', /require\\('react'\\)/.test(clientSrc) && /require\\('react-dom'\\)/.test(clientSrc))\ncheck('client-slot-registration', /ctx\\.slots\\.inject\\('sidebar\\.footer\\.action'/.test(clientSrc) && /ctx\\.slots\\.register\\(/.test(clientSrc))\ncheck('client-official-css-injection', /data-plugin-css/.test(clientSrc) && /--dsw-alias-/.test(clientSrc))\n\n// ---------- 5. hms_emulator degradation (no devecocli in fake ctx) ----------\nconst emu = registered.find((t) => t.name === 'hms_emulator')\nif (emu) {\n  const er = await emu.execute({ action: 'list' }, exec)\n  check('emulator-degraded', er.ok === false && /devecocli|install/i.test((er.error || '') + (er.hint || '')), JSON.stringify(er))\n} else {\n  console.log('SKIP [emulator-tool-registered] 未实现')\n}\n\n// ---------- 6. hms_build workspace boundary precheck ----------\nconst reg2 = []\nmod.apply({\n  get(n) { if (n === 'sandboxPolicy') return { resolve: () => ({ mode: 'workspace-write', workspaceRoot: 'F:/session-ws' }) }; return undefined },\n  inject() {},\n  shell: makeFakeShell(DEFAULT_RULES, seen),\n  tools: { register: (d) => reg2.push(d) },\n  effect: (fn) => fn(),\n})\nconst build2 = reg2.find((t) => t.name === 'hms_build')\nconst br = await build2.execute({ action: 'build', projectPath: 'F:/other/proj' }, exec)\ncheck('build-boundary', br.ok === false && br.outsideWorkspace === true && /工作区之外/.test(br.error || ''), JSON.stringify({ ok: br.ok, outside: br.outsideWorkspace }))\n\n// ---------- 7. client bundle replay (official slots contract) ----------\n// Executes the real browser bundle in Node: apply() runs against a fake slots\n// service (capturing the shell.overlay registration), then the registered\n// React component is shallow-rendered with a minimal hook runtime — FAB\n// present, panel hidden by default, toggle reveals it. This catches the class\n// of bug that broke the loader entry in v0.7.0 (undefined.then), end to end.\nfunction makeFakeReact() {\n  const hooks = []\n  let hIdx = 0\n  return {\n    __reset() { hIdx = 0 },\n    useState(init) {\n      const i = hIdx++\n      if (!(i in hooks)